 	struct vm_area_struct *vma;
 	unsigned long populate = 0;
 	unsigned long ret = -EINVAL;
-	struct file *file;
+	struct file *file = NULL;

 	pr_warn_once("%s (%d) uses deprecated remap_file_pages() syscall. See Documentation/mm/remap_file_pages.rst.\n",
 		     current->comm, current->pid);
@@ -1658,13 +1658,64 @@ SYSCALL_DEFINE5(remap_file_pages, unsigned long, start, unsigned long, size,
 	if (pgoff + (size >> PAGE_SHIFT) < pgoff)
 		return ret;

-	if (mmap_write_lock_killable(mm))
+	if (mmap_read_lock_killable(mm))
 		return -EINTR;

 	vma = vma_lookup(mm, start);

+	if (vma && (vma->vm_flags & VM_SHARED)) {
+		file = get_file(vma->vm_file);
+		prot |= vma->vm_flags & VM_READ ? PROT_READ : 0;
+		prot |= vma->vm_flags & VM_WRITE ? PROT_WRITE : 0;
+		prot |= vma->vm_flags & VM_EXEC ? PROT_EXEC : 0;
+
+		flags &= MAP_NONBLOCK;
+		flags |= MAP_SHARED | MAP_FIXED | MAP_POPULATE;
+		if (vma->vm_flags & VM_LOCKED)
+			flags |= MAP_LOCKED;
+	}
+
+	mmap_read_unlock(mm);
+
+	if (file) {
+		ret = security_mmap_file(file, prot, flags);
+		if (ret) {
+			fput(file);
+			return ret;
+		}
+	}
+
+	if (mmap_write_lock_killable(mm)) {
+		if (file)
+			fput(file);
+		return -EINTR;
+	}
+
+	vma = vma_lookup(mm, start);
+
 	if (!vma || !(vma->vm_flags & VM_SHARED))
-		goto out;
+		goto out_fput;
+
+	if (vma->vm_file != file)
+		goto out_fput;
+
+	if (vma->vm_flags & VM_LOCKED) {
+		if (!(flags & MAP_LOCKED))
+			goto out_fput;
+	} else {
+		if (flags & MAP_LOCKED)
+			goto out_fput;
+	}
+
+	{
+		unsigned long new_prot = 0;
+
+		new_prot |= vma->vm_flags & VM_READ ? PROT_READ : 0;
+		new_prot |= vma->vm_flags & VM_WRITE ? PROT_WRITE : 0;
+		new_prot |= vma->vm_flags & VM_EXEC ? PROT_EXEC : 0;
+		if (new_prot != prot)
+			goto out_fput;
+	}

 	if (start + size > vma->vm_end) {
 		VMA_ITERATOR(vmi, mm, vma->vm_end);
@@ -1673,13 +1724,13 @@ SYSCALL_DEFINE5(remap_file_pages, unsigned long, start, unsigned long, size,
 		for_each_vma_range(vmi, next, start + size) {
 			/* hole between vmas ? */
 			if (next->vm_start != prev->vm_end)
-				goto out;
+				goto out_fput;

 			if (next->vm_file != vma->vm_file)
-				goto out;
+				goto out_fput;

 			if (next->vm_flags != vma->vm_flags)
-				goto out;
+				goto out_fput;

 			if (start + size <= next->vm_end)
 				break;
@@ -1688,26 +1739,14 @@ SYSCALL_DEFINE5(remap_file_pages, unsigned long, start, unsigned long, size,
 		}

 		if (!next)
-			goto out;
+			goto out_fput;
 	}

-	prot |= vma->vm_flags & VM_READ ? PROT_READ : 0;
-	prot |= vma->vm_flags & VM_WRITE ? PROT_WRITE : 0;
-	prot |= vma->vm_flags & VM_EXEC ? PROT_EXEC : 0;
-
-	flags &= MAP_NONBLOCK;
-	flags |= MAP_SHARED | MAP_FIXED | MAP_POPULATE;
-	if (vma->vm_flags & VM_LOCKED)
-		flags |= MAP_LOCKED;
-
-	file = get_file(vma->vm_file);
-	ret = security_mmap_file(vma->vm_file, prot, flags);
-	if (ret)
-		goto out_fput;
 	ret = do_mmap(vma->vm_file, start, size,
 			prot, flags, 0, pgoff, &populate, NULL);
 out_fput:
-	fput(file);
+	if (file)
+		fput(file);
 out:
 	mmap_write_unlock(mm);
 	if (populate)

