@@ -7276,6 +7276,26 @@ int ring_buffer_map(struct trace_buffer *buffer, int cpu,
 	return err;
 }

+void ring_buffer_vm_open(struct trace_buffer *buffer, int cpu)
+{
+	struct ring_buffer_per_cpu *cpu_buffer;
+
+	if (!cpumask_test_cpu(cpu, buffer->cpumask))
+		return;
+
+	cpu_buffer = buffer->buffers[cpu];
+
+	guard(mutex)(&cpu_buffer->mapping_lock);
+	/*
+	 * This is called from the vm_ops->open() callback. The VMA is being
+	 * copied or split. The VMA is already mapped, so just increment the
+	 * refcount.
+	 */
+	if (!WARN_ON_ONCE(!cpu_buffer->user_mapped))
+		__rb_inc_dec_mapped(cpu_buffer, true);
+}
+EXPORT_SYMBOL_GPL(ring_buffer_vm_open);
+
 int ring_buffer_unmap(struct trace_buffer *buffer, int cpu)
 {
 	struct ring_buffer_per_cpu *cpu_buffer;
